import RNIap from 'react-native-iap';
export async function buy(){
  await RNIap.initConnection();
  const products=await RNIap.getProducts({skus:['{{product_id}}']});
  if(!products.length)throw new Error('no product');
  const purchase=await RNIap.requestPurchase({sku:'{{product_id}}'});
  await RNIap.finishTransaction({purchase:purchase as any,isConsumable:true});
  return purchase;}
